import React from 'react';
import styled from 'styled-components';

const CartPage = () => {
  return (
    <CartContainer>
      <Header>
        <Logo>
          <img src="your-logo-url-here" alt="Logo" />
        </Logo>
        <SearchBar placeholder="Search" />
        <NavLinks>
          <NavLink>Home</NavLink>
          <NavLink>About Us</NavLink>
          <NavLink>Sarees</NavLink>
          <NavLink>Jewellery</NavLink>
          <Icons>
            <Icon>🛒</Icon>
            <Icon>👤</Icon>
          </Icons>
        </NavLinks>
      </Header>
      <Main>
        <CartItems>
          <SectionTitle>MY CART</SectionTitle>
          <Item>
            <ItemImage src="jewellery-image-url" alt="Jewellery" />
            <ItemDetails>
              <ItemName>jewellery name</ItemName>
              <QuantityControl>
                <QuantityButton>-</QuantityButton>
                <Quantity>1</Quantity>
                <QuantityButton>+</QuantityButton>
              </QuantityControl>
            </ItemDetails>
          </Item>
          <Item>
            <ItemImage src="saree-image-url" alt="Saree" />
            <ItemDetails>
              <ItemName>saree name</ItemName>
              <QuantityControl>
                <QuantityButton>-</QuantityButton>
                <Quantity>2</Quantity>
                <QuantityButton>+</QuantityButton>
              </QuantityControl>
            </ItemDetails>
          </Item>
        </CartItems>
        <CartSubtotal>
          <SubtotalTitle>CART SUBTOTAL</SubtotalTitle>
          <SubtotalItem>
            <SubtotalImage src="jewellery-image-url" alt="Jewellery" />
            <SubtotalDetails>
              <SubtotalItemName>jewellery name</SubtotalItemName>
              <SubtotalPrice>Rs.5000000</SubtotalPrice>
            </SubtotalDetails>
          </SubtotalItem>
          <SubtotalItem>
            <SubtotalImage src="saree-image-url" alt="Saree" />
            <SubtotalDetails>
              <SubtotalItemName>saree name</SubtotalItemName>
              <SubtotalPrice>Rs.5000000</SubtotalPrice>
            </SubtotalDetails>
          </SubtotalItem>
          <Total>
            SUBTOTAL: Rs.10000000
          </Total>
          <CheckoutButton>CHECKOUT</CheckoutButton>
        </CartSubtotal>
      </Main>
      <Footer>
        <FooterText>TIMELESS ELEGANCE DRAPED IN TRADITION</FooterText>
        <FooterContact>
          <FooterLocation>123 Anywhere St., Any City, ST 12345</FooterLocation>
          <FooterPhone>123-456-7890</FooterPhone>
          <FooterEmail>about@sareeboutique.com</FooterEmail>
        </FooterContact>
        <SocialLinks>
          <SocialIcon>📸</SocialIcon>
          <SocialIcon>📘</SocialIcon>
          <SocialIcon>🐦</SocialIcon>
        </SocialLinks>
      </Footer>
    </CartContainer>
  );
};

export default CartPage;

const CartContainer = styled.div`
  font-family: Arial, sans-serif;
`;

// Header Styling
const Header = styled.header`
  display: flex;
  align-items: center;
  padding: 10px;
  background-color: #D08C8A;
`;

const Logo = styled.div`
  margin-right: auto;
`;

const SearchBar = styled.input`
  margin: 0 20px;
  padding: 5px;
`;

const NavLinks = styled.div`
  display: flex;
  align-items: center;
`;

const NavLink = styled.a`
  margin: 0 15px;
  color: black;
  text-decoration: none;
`;

const Icons = styled.div`
  display: flex;
  align-items: center;
`;

const Icon = styled.div`
  margin-left: 15px;
`;

// Main Content Styling
const Main = styled.main`
  display: flex;
  padding: 20px;
  background-color: #E5CBB2;
`;

const CartItems = styled.div`
  flex: 1;
`;

const SectionTitle = styled.h2`
  font-size: 24px;
  margin-bottom: 20px;
`;

const Item = styled.div`
  display: flex;
  align-items: center;
  margin-bottom: 20px;
`;

const ItemImage = styled.img`
  width: 50px;
  height: 50px;
  margin-right: 20px;
`;

const ItemDetails = styled.div``;

const ItemName = styled.div`
  font-size: 18px;
`;

const QuantityControl = styled.div`
  display: flex;
  align-items: center;
`;

const QuantityButton = styled.button`
  background-color: #B23A48;
  color: white;
  border: none;
  padding: 5px 10px;
  margin: 0 5px;
`;

const Quantity = styled.span``;

// Cart Subtotal Styling
const CartSubtotal = styled.div`
  flex: 1;
  padding: 20px;
`;

const SubtotalTitle = styled.h2`
  font-size: 24px;
  margin-bottom: 20px;
`;

const SubtotalItem = styled.div`
  display: flex;
  align-items: center;
  margin-bottom: 20px;
`;

const SubtotalImage = styled.img`
  width: 50px;
  height: 50px;
  margin-right: 20px;
`;

const SubtotalDetails = styled.div``;

const SubtotalItemName = styled.div`
  font-size: 18px;
`;

const SubtotalPrice = styled.div``;

const Total = styled.div`
  font-size: 20px;
  font-weight: bold;
  margin-top: 20px;
`;

const CheckoutButton = styled.button`
  background-color: #A45B3F;
  color: white;
  border: none;
  padding: 10px 20px;
  font-size: 18px;
  margin-top: 20px;
`;

// Footer Styling
const Footer = styled.footer`
  padding: 20px;
  background-color: #D08C8A;
  text-align: center;
`;

const FooterText = styled.div`
  font-size: 16px;
  margin-bottom: 10px;
`;

const FooterContact = styled.div`
  font-size: 14px;
  margin-bottom: 10px;
`;

const FooterLocation = styled.div``;

const FooterPhone = styled.div``;

const FooterEmail = styled.div``;

const SocialLinks = styled.div`
  display: flex;
  justify-content: center;
`;

const SocialIcon = styled.div`
  margin: 0 10px;
`;
